/**
 * Undo/redo — snapshot-based history (ADR-0003). Prompt documents are small,
 * so storing immutable document references beats operational transforms in
 * simplicity and debuggability. Rapid consecutive user edits (typing) within
 * `mergeWindowMs` collapse into a single undo step.
 */
export const DEFAULT_HISTORY_OPTIONS = {
  limit: 200,
  mergeWindowMs: 500
};
export class EditorHistory {
  options;
  /** States we can go back TO. */
  undoStack = [];
  /** States we can go forward TO. */
  redoStack = [];
  constructor(options = {}) {
    this.options = {
      ...DEFAULT_HISTORY_OPTIONS,
      ...options
    };
  }
  get canUndo() {
    return this.undoStack.length > 0;
  }
  get canRedo() {
    return this.redoStack.length > 0;
  }
  /**
   * Record a change. `previous` is the state BEFORE the change; documents are
   * immutable so no cloning is needed.
   */
  record(previous, options = {}) {
    const label = options.label ?? 'edit';
    this.redoStack = [];
    const top = this.undoStack[this.undoStack.length - 1];
    const shouldMerge = options.merge === true && top !== undefined && top.label === label && Date.now() - top.timestamp <= this.options.mergeWindowMs;
    if (!shouldMerge) {
      this.undoStack.push({
        ...previous,
        label,
        timestamp: Date.now()
      });
      if (this.undoStack.length > this.options.limit) this.undoStack.shift();
    }
  }
  /** Return the state to restore, or null when nothing to undo. */
  undo(current) {
    const entry = this.undoStack.pop();
    if (!entry) return null;
    this.redoStack.push({
      ...current,
      label: entry.label,
      timestamp: Date.now()
    });
    return {
      document: entry.document,
      selection: entry.selection
    };
  }
  /** Return the state to restore, or null when nothing to redo. */
  redo(current) {
    const entry = this.redoStack.pop();
    if (!entry) return null;
    this.undoStack.push({
      ...current,
      label: entry.label,
      timestamp: Date.now()
    });
    return {
      document: entry.document,
      selection: entry.selection
    };
  }
  setOptions(options) {
    this.options = {
      ...this.options,
      ...options
    };
  }
  getOptions() {
    return {
      ...this.options
    };
  }
  reset() {
    this.undoStack = [];
    this.redoStack = [];
  }
}
